local function pool(ctx,p)local seen,r={},{};for _,x in ipairs(ctx:minion_death_records(p))do if not seen[x.card_id]then seen[x.card_id]=true;r[#r+1]=x.card_id end end return r end
local function upgrade(next_id)return{{event="spell_cast",timing="after",active_zones={"hand"},condition=function(ctx,self,event)return event.player==ctx:controller(self)and event.player_cast end,effect=function(ctx,self)local n=ctx:get_data(self,"diamond_spells")+1;ctx:set_data(self,"diamond_spells",n);if n>=4 then cardlib.effects.transform(ctx, self,next_id)end end}}end
local function stone(id,name,text,count,next_id)local x={id=id,name=name,text=text,set="LOOTAPALOOZA",type="spell",class="priest",collectible=false,spell_school="holy",cost=7};if next_id then x.triggers=upgrade(next_id)end;x.on_play=function(ctx,self)ctx:set_data(self,"diamond_left",count);ctx:continue_with("diamond_choose")end;x.diamond_choose=function(ctx,self)if ctx:get_data(self,"diamond_left")<=0 or #ctx:board(ctx:controller(self))>=7 then return end;local choices={};for _,cid in ipairs(pool(ctx,ctx:controller(self)))do if ctx:get_data(self,"diamond_used:"..cid)==0 then choices[#choices+1]=cid end end;if #choices>0 then ctx:random_value(choices,"diamond_summon")end end;x.diamond_summon=function(ctx,self,cid)ctx:summon(ctx:controller(self),cid);ctx:set_data(self,"diamond_used:"..cid,1);local n=ctx:get_data(self,"diamond_left")-1;ctx:set_data(self,"diamond_left",n);if n>0 then ctx:continue_with("diamond_choose")end end;return x end
local card=stone("LOOT_507","Lesser Diamond Spellstone","Resurrect 2 different friendly minions. <i>(Cast 4 spells to upgrade.)</i>",2,"LOOT_507t");card.api_version=1;card.collectible=true;card.rarity="rare";card.tokens={stone("LOOT_507t","Diamond Spellstone","Resurrect 3 different friendly minions.",3,"LOOT_507t2"),stone("LOOT_507t2","Greater Diamond Spellstone","Resurrect 4 different friendly minions.",4,nil)};return card
